window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-28401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτίπλανος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 627 na letra ν · nº geral 28401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νυκτίπλαγκτος. 〈νύξ, πλάνη〉</p></section></article>\n<article id=\"entry-dgp-28402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτίπολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 628 na letra ν · nº geral 28402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vagueia à noite; que faz evoluções à noite. 〈νύξ, πολέω〉</p></section></article>\n<article id=\"entry-dgp-28403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτίσεμνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 629 na letra ν · nº geral 28403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">solenemente celebrado à noite. 〈νύξ, σεμνός〉</p></section></article>\n<article id=\"entry-dgp-28404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτιφαής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 630 na letra ν · nº geral 28404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 resplandecente à noite 2 que aparece à noite. 〈νύξ, φάος〉</p></section></article>\n<article id=\"entry-dgp-28405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτίφοιτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 631 na letra ν · nº geral 28405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que costuma vir à noite; noturno. 〈νύξ, φοιτάω〉</p></section></article>\n<article id=\"entry-dgp-28406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτιφρούρητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 632 na letra ν · nº geral 28406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vigia à noite. 〈νύξ, φρουρέω〉</p></section></article>\n<article id=\"entry-dgp-28407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτογραφία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 633 na letra ν · nº geral 28407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de escrever à noite, na vigília. 〈νύξ, γράφω〉</p></section></article>\n<article id=\"entry-dgp-28408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτοθήρας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 634 na letra ν · nº geral 28408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caçador noturno. 〈νύξ, θηράω〉</p></section></article>\n<article id=\"entry-dgp-28409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτομαχέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 635 na letra ν · nº geral 28409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combater à noite. 〈νύξ, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-28410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτομαχία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 636 na letra ν · nº geral 28410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">combate noturno. 〈νύξ, μάχη〉</p></section></article>\n<article id=\"entry-dgp-28411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτοπορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 637 na letra ν · nº geral 28411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">viajar à noite. 〈νύξ, πόρος〉</p></section></article>\n<article id=\"entry-dgp-28412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτοπορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 638 na letra ν · nº geral 28412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">marcha noturna. 〈νύξ, πόρος〉</p></section></article>\n<article id=\"entry-dgp-28413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 639 na letra ν · nº geral 28413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que trabalha à noite. 〈νύξ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-28414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτοῦρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 640 na letra ν · nº geral 28414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vigilante noturno, ref. ao planeta Sa­turno. 〈νύξ, οὖρος2〉</p></section></article>\n<article id=\"entry-dgp-28415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτοφυλακέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 641 na letra ν · nº geral 28415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 montar guarda à noite para vigiar algo, ac. 2 ser chefe da guarda noturna, em Roma. 〈νύξ, φύλαξ〉</p></section></article>\n<article id=\"entry-dgp-28416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτοφύλαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 642 na letra ν · nº geral 28416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guarda da noite; sentinela noturna. 〈νύξ, φύλαξ〉</p></section></article>\n<article id=\"entry-dgp-28417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτῷον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 643 na letra ν · nº geral 28417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">templo da noite. 〈νύξ〉</p></section></article>\n<article id=\"entry-dgp-28418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυκτωπός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 644 na letra ν · nº geral 28418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">provocado por visões noturnas. 〈νύξ, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-28419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύκτωρ</h1><div class=\"entry-meta\"><span>DGP · ordem 645 na letra ν · nº geral 28419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. à noite; nas trevas. 〈νύξ〉</p></section></article>\n<article id=\"entry-dgp-28420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύμφα</h1><div class=\"entry-meta\"><span>DGP · ordem 646 na letra ν · nº geral 28420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = νύμφη.</p></section></article>\n<article id=\"entry-dgp-28421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφαγωγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 647 na letra ν · nº geral 28421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduzir a noiva 2 concluir um casamento. 〈νυμφαγωγός〉</p></section></article>\n<article id=\"entry-dgp-28422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφαγωγία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 648 na letra ν · nº geral 28422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cortejo nupcial que conduz a noiva da casa de seu pai à casa do noivo. 〈νυμφαγωγός〉</p></section></article>\n<article id=\"entry-dgp-28423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυνφαγωγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 649 na letra ν · nº geral 28423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 condutor da noiva no cortejo nupcial; padrinho 2 aquele que combina o casamento para outrem.</p></section></article>\n<article id=\"entry-dgp-28424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 650 na letra ν · nº geral 28424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ninfas; consagrado às ninfas ♦ ἡ νυμ­φαία 2 ninféia, planta ♦ τὸ νυμφαῖον 3 santuário das ninfas; ninfeu. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφεῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 651 na letra ν · nº geral 28425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 da noiva; da recém-casada; nupcial ♦ τὸ νυμφεῖον 2 quarto nupcial 3 pl. ritos matrimoniais; casamento 4 pl. noiva. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύμφευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 652 na letra ν · nº geral 28426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 casamento 2 noiva; esposa. 〈νυμ­φεύω〉</p></section></article>\n<article id=\"entry-dgp-28427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφευτρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 653 na letra ν · nº geral 28427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acompanhante da noiva no cortejo nupcial; madrinha 2 noiva; esposa. 〈νυμφεύω〉</p></section></article>\n<article id=\"entry-dgp-28428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 654 na letra ν · nº geral 28428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dar uma filha como esposa; casar uma filha ♦ at. e méd. 2 (homem) desposar uma mulher, ac. 3 (mulher) casar-se com, dat. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύμφη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 655 na letra ν · nº geral 28429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 noiva; a recém-casada 2 nora 3 enteada 4 boneca 5 larva de abelha 6 formiga alada 7 Anat. reentrância entre o lábio e o queixo 8 Anat. clitóris 9 nicho em um muro 10 extremidade superior da relha do arado ♦ αἱ Νύμφαι 11 Ninfas, divindades que povoam as águas, bosques, montes e prados.</p></section></article>\n<article id=\"entry-dgp-28430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφήϊος</h1><div class=\"entry-meta\"><span>DGP · ordem 656 na letra ν · nº geral 28430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = νυμφεῖος.</p></section></article>\n<article id=\"entry-dgp-28431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφίδιος, η</h1><div class=\"entry-meta\"><span>DGP · ordem 657 na letra ν · nº geral 28431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, όν nupcial. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 658 na letra ν · nº geral 28432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">matrimonial; nupcial. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύμφιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 659 na letra ν · nº geral 28433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de casamento; matrimonial 2 recém-casado. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφίος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 660 na letra ν · nº geral 28434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 jovem esposo; noivo 2 pl. esposos 3 genro. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφόκλαυτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 661 na letra ν · nº geral 28435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que é motivo de choro para as esposas. 〈νύμφη, κλαίω〉</p></section></article>\n<article id=\"entry-dgp-28436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφοκομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 662 na letra ν · nº geral 28436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 adornar uma jovem esposa 2 intr. adornar-se como jovem esposa. 〈νυμφοκόμος〉</p></section></article>\n<article id=\"entry-dgp-28437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφοκόμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 663 na letra ν · nº geral 28437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que adorna a jovem esposa; nupcial. 〈νύμφη, κομέω〉</p></section></article>\n<article id=\"entry-dgp-28438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφόληπτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 664 na letra ν · nº geral 28438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">possuído pelas ninfas; delirante. 〈νύμφη, λαμβάνω〉</p></section></article>\n<article id=\"entry-dgp-28439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφοστολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 665 na letra ν · nº geral 28439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acompanhar em cortejo a noiva ou o noivo 2 acompanhar em cortejo os noivos. 〈νύμφη, στέλλω〉</p></section></article>\n<article id=\"entry-dgp-28440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφότιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 666 na letra ν · nº geral 28440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que é ou que se faz em honra da noiva; nupcial. 〈νύμφη, τιμή〉</p></section></article>\n<article id=\"entry-dgp-28441\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυμφών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 667 na letra ν · nº geral 28441</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quarto nupcial 2 tard. templo de Dio­niso, Deméter e Perséfone. 〈νύμφη〉</p></section></article>\n<article id=\"entry-dgp-28442\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῦν</h1><div class=\"entry-meta\"><span>DGP · ordem 668 na letra ν · nº geral 28442</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. agora. 1 (tempo pres.) agora; no presente; neste exato momento; atualmente; τὰ νῦν agora, neste momento, νῦν δή precisamente agora, νῦν ἤδη desde já 2 (tempo pas.) agora mesmo; há pouco 3 (tempo fut.) agora; em seguida; imediatamente; de hoje em diante; daqui a pouco 4 (contraposto ao irreal) agora; na realidade 5 (conseqüência) sendo assim; nessas condições; conseqüentemente; καὶ νῦν agora também; mesmo nessas circunstâncias 1 ἡμεῖς δὲ ὁμοῖοι καὶ τότε καὶ νῦν ἔσμεν tuc. nós somos neste momento os mesmos que éramos então 2 καθάπερ νῦν εἶπες plat. como disseste agora mesmo 3 νῦν αὖτ’ ἐγχείῃ πειράσομαι, αἴ κε τύχωμι hom. e agora de novo tentarei com minha lança na esperança de atingir-te 4 τιμήν πέρ μοι ὄφελλεν Ὀλύμπιος ἐγγυαλίξαι…, νῦν δ’ οὐδέ με τυτθὸν ἔτισεν hom. o Olímpio devia tributar-me honras, mas na realidade não me honrou de maneira alguma 5 Ἰώνων παῖδας δούλους εἶναι ἀντ’ ἐλευθέρων ὄνειδος καὶ ἄλγος μέγιστον μὲν αὑτοῖσι ἡμῖν…, νῦν ὦν πρὸς θεῶν τῶν Ἑλληνίων ῥύσασθε Ἰώνας ἐκ δουλοσύνης her. os filhos dos jônios serem escravos em lugar de livres é uma opróbrio e uma dor enorme para nós mesmos…, sendo assim, então, em nome dos deuses gregos, livrai da escravidão os jônios.</p></section></article>\n<article id=\"entry-dgp-28443\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύν,</h1><div class=\"entry-meta\"><span>DGP · ordem 669 na letra ν · nº geral 28443</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. encl. νυν, e νυ antes de cons., partíc. então, usada 1 para marcar a seqüência do raciocínio: ἦκε δὲ βέλος, οἱ δέ νυ λαοὶ θνῇσκον hom. ele lançou um dardo e então os soldados morreram 2 com um imper.: ἄκουσον δή νυν plat. escuta, então 3 para reforçar uma afirm. ou uma neg.: ἦ ῥά νυν hom. sim, sem dúvida!, οὔ νυ hom. não mesmo.</p></section></article>\n<article id=\"entry-dgp-28444\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυνί</h1><div class=\"entry-meta\"><span>DGP · ordem 670 na letra ν · nº geral 28444</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., át. = νῦν.</p></section></article>\n<article id=\"entry-dgp-28445\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύξ, νυκτός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 671 na letra ν · nº geral 28445</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 noite: μέσαι νύκτες meia-noite; loc. adv. περὶ μέσας νύκτας xen. por volta da meia noite, πρωΐτερον μέσων νυκτῶν tuc. antes da meia noite, ἔξω μέσων νυκτῶν dem. depois da meia noite, νυκτός à noite, em certo momento da noite, νυκτὸς τῆσδε sóf. nesta noite, τῆς παρελθούσης νυκτός plat. na noite passada, ἐκ νυκτός xen. desde o anoitecer, νυκτί hom., ἐν νυκτί át. na noite, ἐπὶ νυκτί hom. à noite, νύκτα durante a noite, ἀνὰ νύκτα hom. durante a noite, noite afora, διὰ νύκτα hom. ao longo da noite, εἰς νύκτα xen. ao cair da noite 2 noite; escuridão; trevas: ἀμφὶ δὲ ὄσσε κελαινὴ νὺξ ἐκάλυψε hom. uma noite sombria cobriu-lhe os olhos ♦ Νύξ 3 Noite, person.</p></section></article>\n<article id=\"entry-dgp-28446\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύξαι</h1><div class=\"entry-meta\"><span>DGP · ordem 672 na letra ν · nº geral 28446</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de νύσσω.</p></section></article>\n<article id=\"entry-dgp-28447\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύξις, έως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 673 na letra ν · nº geral 28447</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de picar; picada. 〈νύσσω〉</p></section></article>\n<article id=\"entry-dgp-28448\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυός, οῦ (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 674 na letra ν · nº geral 28448</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 enteada 2 nora 3 parenta por aliança 4 recém-casada.</p></section></article>\n<article id=\"entry-dgp-28449\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νῦσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 675 na letra ν · nº geral 28449</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Nisa, n. de diversas cidades, e de montes onde Dioniso era cultuado.</p></section></article>\n<article id=\"entry-dgp-28450\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νυσαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 676 na letra ν · nº geral 28450</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Nisa 2 do monte Nisa, na Eubéia ♦ ὁ Νυσαῖος 3 Niseu; o deus do monte Nisa, ref. a Dioniso 4 Niseu, n. de h. 〈Νῦσα〉</p></section></article>\n<article id=\"entry-dgp-28451\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νυσήϊος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 677 na letra ν · nº geral 28451</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Νυσαῖος.</p></section></article>\n<article id=\"entry-dgp-28452\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νύσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 678 na letra ν · nº geral 28452</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Νυσαῖος.</p></section></article>\n<article id=\"entry-dgp-28453\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύσσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 679 na letra ν · nº geral 28453</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 marco do ponto de retorno, no estádio 2 ponto de partida e de chegada, no estádio 3 meta; objetivo.</p></section></article>\n<article id=\"entry-dgp-28454\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 680 na letra ν · nº geral 28454</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. νύττω (fut. νύξω, aor. ἔνυξα, perf. desus., pas. aor. ἐνύχθην, aor.2 ἐνύγην, perf. νένυγμαι) 1 picar; espetar; furar; ferir 2 ferir; golpear; percutir 3 fustigar; espicaçar.</p></section></article>\n<article id=\"entry-dgp-28455\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυστάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 681 na letra ν · nº geral 28455</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. νυστάξω, aor. ἐνύστασα e ἐνύσταξα, perf. desus.) 1 cabecear (de sono) 2 adormecer; dormir 3 ser desatento; ser negligente 4 abaixar a cabeça (de tristeza).</p></section></article>\n<article id=\"entry-dgp-28456\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύττω</h1><div class=\"entry-meta\"><span>DGP · ordem 682 na letra ν · nº geral 28456</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = νύσσω.</p></section></article>\n<article id=\"entry-dgp-28457\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νυχθήμερος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 683 na letra ν · nº geral 28457</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que dura um dia e uma noite ♦ τὸ νυχ­θήμερον 2 a duração de um dia e uma noite. 〈νύξ, ἡμέρα〉</p></section></article>\n<article id=\"entry-dgp-28458\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νύχιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 684 na letra ν · nº geral 28458</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que age ou vive à noite; noturno (pessoa) 2 que se faz à noite; da noite; noturno 3 sombrio; obscuro. 〈νύξ〉</p></section></article>\n<article id=\"entry-dgp-28459\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νώ</h1><div class=\"entry-meta\"><span>DGP · ordem 685 na letra ν · nº geral 28459</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom. dual. ép. jôn. e dór. de ἐγώ.</p></section></article>\n<article id=\"entry-dgp-28460\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῷ</h1><div class=\"entry-meta\"><span>DGP · ordem 686 na letra ν · nº geral 28460</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. de νοῦς.</p></section></article>\n<article id=\"entry-dgp-28461\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωδός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 687 na letra ν · nº geral 28461</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem dentes; desdentado 2 embotado. 〈νη-, ὀδούς〉</p></section></article>\n<article id=\"entry-dgp-28462\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νώδυνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 688 na letra ν · nº geral 28462</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem dor 2 que acalma a dor. 〈νη-, ὀδύνη〉</p></section></article>\n<article id=\"entry-dgp-28463\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Νῶε</h1><div class=\"entry-meta\"><span>DGP · ordem 689 na letra ν · nº geral 28463</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (ὁ) bíbl. Noé.</p></section></article>\n<article id=\"entry-dgp-28464\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νώθεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 690 na letra ν · nº geral 28464</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lentidão 2 lerdeza de espírito; obtusidade. 〈νωθής〉</p></section></article>\n<article id=\"entry-dgp-28465\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 691 na letra ν · nº geral 28465</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lento; demorado 2 de espírito lento; obtuso; embotado 3 preguiçoso; indolente.</p></section></article>\n<article id=\"entry-dgp-28466\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωθρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 692 na letra ν · nº geral 28466</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lento; demorado 2 preguiçoso; indolente 3 frágil; lânguido 4 de espírito embotado; obtuso 5 que torna indolente. 〈νωθής〉</p></section></article>\n<article id=\"entry-dgp-28467\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωθρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 693 na letra ν · nº geral 28467</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lentidão; indolência. 〈νωθρός〉</p></section></article>\n<article id=\"entry-dgp-28468\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῶϊ</h1><div class=\"entry-meta\"><span>DGP · ordem 694 na letra ν · nº geral 28468</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">nom., νῶϊν gen. ou dat., ép. jôn e dór. de ἐγώ.</p></section></article>\n<article id=\"entry-dgp-28469\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωΐτερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 695 na letra ν · nº geral 28469</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nosso; de nós dois 2 nosso (= ἡμέτερος). 〈νῶϊ, -τερος〉</p></section></article>\n<article id=\"entry-dgp-28470\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωλεμές</h1><div class=\"entry-meta\"><span>DGP · ordem 696 na letra ν · nº geral 28470</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem interrupção; sem trégua; obstinadamente.</p></section></article>\n<article id=\"entry-dgp-28471\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωλεμέως</h1><div class=\"entry-meta\"><span>DGP · ordem 697 na letra ν · nº geral 28471</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = νωλεμές.</p></section></article>\n<article id=\"entry-dgp-28472\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 698 na letra ν · nº geral 28472</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐνώμηκα, perf. νενώμηκα) 1 repartir; distribuir; partilhar 2 pôr em movimento; manejar; brandir 3 dirigir; governar; conduzir; guiar 4 revirar; agitar no espírito 5 observar; refletir; meditar ♦ méd. 6 manejar 7 ocupar (terra). 〈νέμω〉</p></section></article>\n<article id=\"entry-dgp-28473\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῷν</h1><div class=\"entry-meta\"><span>DGP · ordem 699 na letra ν · nº geral 28473</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">contr. = νῶϊν.</p></section></article>\n<article id=\"entry-dgp-28474\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νώνυμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 700 na letra ν · nº geral 28474</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem nome; sem renome; sem glória 2 que não pronuncia o nome de, gen. 〈νη-, ὄνομα〉</p></section></article>\n<article id=\"entry-dgp-28475\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῶροψ, οπος</h1><div class=\"entry-meta\"><span>DGP · ordem 701 na letra ν · nº geral 28475</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) resplandecente; brilhante.</p></section></article>\n<article id=\"entry-dgp-28476\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωσάμενος, νώσασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 702 na letra ν · nº geral 28476</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. e inf. aor. méd. jôn. de νοέω.</p></section></article>\n<article id=\"entry-dgp-28477\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωτιαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 703 na letra ν · nº geral 28477</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do dorso; dorsal. 〈νῶτος〉</p></section></article>\n<article id=\"entry-dgp-28478\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωτίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 704 na letra ν · nº geral 28478</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. ἐνώτισα) 1 virar as costas; escapar; fugir 2 cobrir as costas de; vestir, ac. 3 deslizar sobre o dorso; percorrer o dorso do mar, ac. 〈νῶτος〉</p></section></article>\n<article id=\"entry-dgp-28479\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῶτον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 705 na letra ν · nº geral 28479</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 costas; dorso; espinha dorsal: τὰ νῶτα ou τὸ νῶτον ἐπιστρέφειν, ἐντρέπειν, δεῖξαι virar ou mostrar as costas, i.e., fugir, κατὰ νώτου τινὶ ἐπιγίγνεσθαι tuc. agarrar alguém pelas costas 2 superfície convexa; dorso (do mar, da terra) 3 abóbada do céu 4 pico de montanha 5 cubo de eixo de roda 6 roda de carro.</p></section></article>\n<article id=\"entry-dgp-28480\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νῶτος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 706 na letra ν · nº geral 28480</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">νῶτον.</p></section></article>\n<article id=\"entry-dgp-28481\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωτοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 707 na letra ν · nº geral 28481</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que leva nas costas ♦ τὸ νωτοφόρον 2 besta de carga. 〈νῶτον, φέρω〉</p></section></article>\n<article id=\"entry-dgp-28482\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωχελής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 708 na letra ν · nº geral 28482</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se move lentamente; pesado; lento 2 indolente; preguiçoso ♦ τὸ νωχελές 3 Medic. placenta.</p></section></article>\n<article id=\"entry-dgp-28483\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">νωχελία, ας,</h1><div class=\"entry-meta\"><span>DGP · ordem 709 na letra ν · nº geral 28483</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. -ίη, ης (ἡ) lentidão; indolência; preguiça. 〈νωχελής〉</p></section></article>\n<article id=\"entry-dgp-28484\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ξ, ξ (ξῖ)</h1><div class=\"entry-meta\"><span>DGP · ordem 1 na letra ξ · nº geral 28484</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">indecl. (τό) 1 ksi, 14ª letra do alfabeto grego ♦ num. 2 ξʹ = 60 ou 60º 3 ͵ξ = 60.000 ou 60.000º.</p></section></article>\n<article id=\"entry-dgp-28485\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2 na letra ξ · nº geral 28485</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ξανῶ, aor. ἔξηνα; pas. aor. ἐξάνθην, perf. ἔξασ­μαι e ἔξαμμαι) 1 cardar; pentear: ξ. εἴρια hom. cardar lã, ξ. εἰς καλαθίσκον κοινὴν εὔνοιαν ar. cardar e pôr numa cestinha a boa-vontade geral, ξ. εἰς πῦρ cardar no fogo, i.e., trabalhar em vão 2 preparar; fiar; tecer (lã, peplo) 3 golpear; dilacerar; ferir (corpo, face): ξ. κατὰ τοῦ νώτου πολλάς [πληγάς] dem. aplicar no dorso muitos golpes, ξ. ταῖς ῥάβδοις τὸ σῶμα d.h. ferir o corpo com varas 4 sulcar: ξ. παρειὰς δάκρυσιν ant. sulcar as faces com lágrimas.</p></section></article>\n<article id=\"entry-dgp-28486\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξανθόγεως, ως, ων</h1><div class=\"entry-meta\"><span>DGP · ordem 3 na letra ξ · nº geral 28486</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de solo amarelo. 〈ξανθός, γῆ〉</p></section></article>\n<article id=\"entry-dgp-28487\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξανθόθριξ, τριχος</h1><div class=\"entry-meta\"><span>DGP · ordem 4 na letra ξ · nº geral 28487</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 de cabelos louros 2 de cri- na amarela; de pêlos amarelos; baio (cavalo). 〈ξανθός, θρίξ〉</p></section></article>\n<article id=\"entry-dgp-28488\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξανθοκόμης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 5 na letra ξ · nº geral 28488</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de loura cabeleira; louro. 〈ξανθός, κόμης〉</p></section></article>\n<article id=\"entry-dgp-28489\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξανθός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 6 na letra ξ · nº geral 28489</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 louro; amarelo; dourado; ruivo; fulvo (cabelo, pêlo, velo, coisa) 2 amarelo; esverdeado (bile) 3 verde (oliveira) 4 róseo; avermelhado 5 esbranquiçado.</p></section></article>\n<article id=\"entry-dgp-28490\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ξάνθος1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 7 na letra ξ · nº geral 28490</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Xanto, n. de h., de cavalo, de rio.</p></section></article>\n<article id=\"entry-dgp-28491\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ξάνθος2, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 8 na letra ξ · nº geral 28491</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Xanto, cidade da Lícia.</p></section></article>\n<article id=\"entry-dgp-28492\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξεινήϊος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 9 na letra ξ · nº geral 28492</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ξένιος.</p></section></article>\n<article id=\"entry-dgp-28493\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξεινίζω, ξεινικός, ξείνιος, ξεῖνος</h1><div class=\"entry-meta\"><span>DGP · ordem 10 na letra ξ · nº geral 28493</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ξενίζω, ξενικός, ξένιος, ξένος.</p></section></article>\n<article id=\"entry-dgp-28494\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξεναγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 11 na letra ξ · nº geral 28494</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduzir os estrangeiros; ser guia de estrangeiros 2 comandar mercenários. 〈ξεναγός〉</p></section></article>\n<article id=\"entry-dgp-28495\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξεναγός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 12 na letra ξ · nº geral 28495</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 guia ou condutor de estrangeiros 2 comandante de mercenários 3 comandante de divisão de infantaria (256 homens). 〈ξένος, ἡγέομαι〉</p></section></article>\n<article id=\"entry-dgp-28496\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξεναγωγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 13 na letra ξ · nº geral 28496</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ξεναγός. 〈ξένος, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-28497\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξεναπάτας, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 14 na letra ξ · nº geral 28497</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) dór. enganador de estrangeiros ou de hóspedes. 〈ξένος, ἀπατάω〉</p></section></article>\n<article id=\"entry-dgp-28498\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξένη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 15 na letra ξ · nº geral 28498</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de ξένος.</p></section></article>\n<article id=\"entry-dgp-28499\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξενηλασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 16 na letra ξ · nº geral 28499</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">banimento de estrangeiros. 〈ξενηλατέω〉</p></section></article>\n<article id=\"entry-dgp-28500\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ξενηλατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 17 na letra ξ · nº geral 28500</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">banir estrangeiros. 〈ξένος, ἐλαύνω〉</p></section></article>\n";
